package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Caverphone_caverphone_TriageGen0Test {

    private Caverphone caverphone;

    @Before
    public void setUp() {
        caverphone = new Caverphone();
    }

    @Test
    public void testCaverphone_NullInput() {
        assertEquals("1111111111", caverphone.caverphone(null));
    }

    @Test
    public void testCaverphone_EmptyInput() {
        assertEquals("1111111111", caverphone.caverphone(""));
    }

    @Test
    public void testCaverphone_BasicTransformation() {
        // Testing general flow: lowercase, non-alpha removal, replacements, and padding
        // "Apple" -> "apple" -> "3ppl3" -> "PPL" -> "PPL1111111111" -> "PPL1111111"
        // Note: exact output depends on the complex regex chain
        String result = caverphone.caverphone("Apple");
        assertNotNull(result);
        assertEquals(10, result.length());
    }

    @Test
    public void testCaverphone_StartOptions() {
        // Test "cough" -> "cou2f" -> "kouf" -> ...
        assertNotNull(caverphone.caverphone("cough"));
        // Test "rough" -> "rou2f"
        assertNotNull(caverphone.caverphone("rough"));
        // Test "tough" -> "tou2f"
        assertNotNull(caverphone.caverphone("tough"));
        // Test "enough" -> "enou2f"
        assertNotNull(caverphone.caverphone("enough"));
        // Test "trough" -> "trou2f"
        assertNotNull(caverphone.caverphone("trough"));
        // Test "gn" -> "2n"
        assertNotNull(caverphone.caverphone("gnat"));
        // Test "mb" -> "m2"
        assertNotNull(caverphone.caverphone("mbira"));
    }

    @Test
    public void testCaverphone_Replacements() {
        // Test cq, ci, ce, cy
        assertNotNull(caverphone.caverphone("cq"));
        assertNotNull(caverphone.caverphone("ci"));
        assertNotNull(caverphone.caverphone("ce"));
        assertNotNull(caverphone.caverphone("cy"));

        // Test tch
        assertNotNull(caverphone.caverphone("watch"));

        // Test c, q, x, v
        assertNotNull(caverphone.caverphone("cat"));
        assertNotNull(caverphone.caverphone("queen"));
        assertNotNull(caverphone.caverphone("box"));
        assertNotNull(caverphone.caverphone("van"));

        // Test dg, tio, tia
        assertNotNull(caverphone.caverphone("edge"));
        assertNotNull(caverphone.caverphone("action"));
        assertNotNull(caverphone.caverphone("partial"));

        // Test d, ph, b, sh, z
        assertNotNull(caverphone.caverphone("dog"));
        assertNotNull(caverphone.caverphone("phone"));
        assertNotNull(caverphone.caverphone("ball"));
        assertNotNull(caverphone.caverphone("ship"));
        assertNotNull(caverphone.caverphone("zebra"));
    }

    @Test
    public void testCaverphone_VowelsAndJ() {
        // Test vowels [aeiou] and j, y
        assertNotNull(caverphone.caverphone("a"));
        assertNotNull(caverphone.caverphone("e"));
        assertNotNull(caverphone.caverphone("i"));
        assertNotNull(caverphone.caverphone("o"));
        assertNotNull(caverphone.caverphone("u"));
        assertNotNull(caverphone.caverphone("j"));

        // Test y patterns (2.0 only)
        assertNotNull(caverphone.caverphone("yes")); 
        assertNotNull(caverphone.caverphone("yellow"));
    }

    @Test
    public void testCaverphone_ConsonantClusters() {
        // Test s+, t+, p+, k+, f+, m+, n+, w, h, r, l
        assertNotNull(caverphone.caverphone("ssss"));
        assertNotNull(caverphone.caverphone("tttt"));
        assertNotNull(caverphone.caverphone("pppp"));
        assertNotNull(caverphone.caverphone("kkkk"));
        assertNotNull(caverphone.caverphone("ffff"));
        assertNotNull(caverphone.caverphone("mmmm"));
        assertNotNull(caverphone.caverphone("nnnn"));
        assertNotNull(caverphone.caverphone("wh"));
        assertNotNull(caverphone.caverphone("h"));
        assertNotNull(caverphone.caverphone("r"));
        assertNotNull(caverphone.caverphone("l"));
    }

    @Test
    public void testCaverphone_SpecialCases() {
        // Test 3gh3 -> 3kh3
        assertNotNull(caverphone.caverphone("3gh3")); // though input is non-alpha, testing regex logic

        // Test gh -> 22
        assertNotNull(caverphone.caverphone("ghost"));

        // Test w3 and wh3
        assertNotNull(caverphone.caverphone("w3"));
        assertNotNull(caverphone.caverphone("wh3"));

        // Test trailing e (2.0 only)
        assertNotNull(caverphone.caverphone("bake"));

        // Test trailing w (2.0 only)
        assertNotNull(caverphone.caverphone("low"));

        // Test trailing r (2.0 only)
        assertNotNull(caverphone.caverphone("car"));

        // Test trailing l (2.0 only)
        assertNotNull(caverphone.caverphone("ball"));
    }

    @Test
    public void testCaverphone_NonAlphaCharacters() {
        // Verify that non-A-Z are removed
        String result = caverphone.caverphone("a!b@c#d$e%f^g&h*i(j)");
        assertNotNull(result);
        assertEquals(10, result.length());
    }
}
